import React, { PropsWithChildren } from 'react';
import styled from 'styled-components';

import { GlobalFontSizeVariables } from './components/GlobalFontSizeVariables.js';
import { SingleValueRenderer } from './components/SingleValueRenderer.js';
import { calculateGridLayout } from './functions/calculate-grid-layout.js';
import { iterateSlots } from './functions/iterate-slots.js';
import { useLabelCount } from './hooks/use-label-count.js';
import { GlobalFontSizeProvider } from './providers/global-font-size-provider.js';
import { Sparkline } from './slots/Sparkline.js';
import { Trend } from './slots/Trend.js';
import { Value } from './slots/Value.js';
import { SingleValueGridAccessorsConfig } from './types/single-value-grid.js';
import { Threshold } from '../../core/types/threshold-types.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { Grid } from '../../layouts-core/grid/Grid.js';
import { useThrottledResizeObserver } from '../core/hooks/useThrottledResizeObserver.js';
import { SingleValueAlignment } from '../single-value/types/single-value.js';

/** Props for the SingleValueGrid component. */
export interface SingleValueGridProps {
  /** The data source for the SingleValueGrid component. */
  data: (number | string | Record<string, unknown>)[];
  /**
   * The default color for the SingleValues.
   * This color will be overwritten by individual colors specified in the SingleValueGridData or thresholds prop.
   */
  color?: string;
  /** Accessor function to override colors for individual SingleValue components. */
  colorAccessor?: string;
  /**
   * Threshold configurations that define conditions to match a given value.
   * These configurations will overwrite the color prop for the corresponding SingleValue components.
   */
  thresholds?: Threshold[];
  /** Accessor function for individual labels of each SingleValue component. */
  labelAccessor?: string;
  /** Accessor function for individual prefix icons of each SingleValue component. */
  prefixIconAccessor?: string;
  /**
   * Horizontal alignment of icons, values, units, labels, and trends within each SingleValue component.
   * @defaultValue 'start'
   */
  alignment?: SingleValueAlignment;
}

/**
 * To be able to make the last row columns distribute the remaining space, we should get the least common multiple.
 * With that calculation done, we get the real number of columns of the grid, and then we make the SingleValues span through the correct number of columns
 */
const StyledGridContainer = /* @__PURE__ */ styled(Grid)({
  height: '100%',
  width: '100%',

  '& > div': {
    overflow: 'hidden',
  },
});

const StyledLastRow = /* @__PURE__ */ styled(Flex)({
  height: '100%',
  width: '100%',

  '& > div': {
    overflow: 'hidden',
  },
});

export const _SingleValueGrid = (
  props: PropsWithChildren<SingleValueGridProps>,
) => {
  const {
    data,
    children,
    colorAccessor,
    labelAccessor,
    prefixIconAccessor,
    ...gridConfig
  } = props;

  const labelCount = useLabelCount(data, labelAccessor);

  const { accessors: slotAccessors, ...slotsConfig } = iterateSlots(children);

  const trendCount = slotsConfig.trend !== undefined ? data.length : 0;

  const accessors: SingleValueGridAccessorsConfig = {
    colorAccessor,
    labelAccessor,
    prefixIconAccessor,
    ...slotAccessors,
  };

  const propsConfig = {
    ...gridConfig,
    ...slotsConfig,
  };

  const { height = 0, width = 0, refCallback } = useThrottledResizeObserver();

  const { rowCount, columnCount, lastRowColumnCount, gap } =
    calculateGridLayout(width, height, data.length);

  const gridItems = data.slice(0, data.length - lastRowColumnCount);
  const lastRowItems = data.slice(-lastRowColumnCount);

  return (
    <GlobalFontSizeProvider
      valueCount={data.length}
      labelCount={labelCount}
      trendCount={trendCount}
    >
      <GlobalFontSizeVariables>
        <StyledGridContainer
          ref={refCallback}
          gridTemplateRows={`repeat(${rowCount}, 1fr)`}
          gridTemplateColumns={`repeat(${columnCount}, 1fr)`}
          style={{
            // Explicitly set this one via the style, as the `gridGap` settable via the
            // props on the `Grid` component needs to be a valid spacing token
            gridGap: gap,
          }}
        >
          {gridItems.map((record, index) => (
            <SingleValueRenderer
              key={index}
              record={record}
              propsConfig={propsConfig}
              accessors={accessors}
            />
          ))}
          <StyledLastRow
            style={{
              // Explicitly set this one via the style, as the `gridGap` settable via the
              // props on the `Grid` component needs to be a valid spacing token
              columnGap: gap,
            }}
            gridColumn={'1 / -1'}
          >
            {lastRowItems.map((record, index) => (
              <SingleValueRenderer
                key={index}
                record={record}
                propsConfig={propsConfig}
                accessors={accessors}
              />
            ))}
          </StyledLastRow>
        </StyledGridContainer>
      </GlobalFontSizeVariables>
    </GlobalFontSizeProvider>
  );
};

_SingleValueGrid['displayName'] = 'SingleValueGrid';

/** The SingleValueGrid component */
export const SingleValueGrid = Object.assign(_SingleValueGrid, {
  Value,
  Trend,
  Sparkline,
});
